    { const char * tb_v1325 = "    sigaltstack(&ss, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v1325; }
    { const char * tb_v1326 = "    struct sigaction sa;\n"; *(const char * *)tb_grow(v_lines) = tb_v1326; }
