    { const char * tb_v3289 = "// клавиши: буквы и цифры — свой код ASCII (A..Z, 0..9), остальные:\n"; *(const char * *)tb_grow(v_lines) = tb_v3289; }
    { const char * tb_v3290 = "enum { TB_K_ENTER = 10, TB_K_ESC = 27, TB_K_SPACE = 32, TB_K_BACK = 8, TB_K_TAB = 9,\n"; *(const char * *)tb_grow(v_lines) = tb_v3290; }
    { const char * tb_v3291 = "       TB_K_UP = 17, TB_K_DOWN = 18, TB_K_RIGHT = 19, TB_K_LEFT = 20, TB_K_SHIFT = 21 };\n"; *(const char * *)tb_grow(v_lines) = tb_v3291; }
    { const char * tb_v3292 = "// ---------- рисование на видеокарте (GPU) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3292; }
    { const char * tb_v3293 = "// Кадр не рисуется точками на процессоре: каждая фигура записывается как «экземпляр»\n"; *(const char * *)tb_grow(v_lines) = tb_v3293; }
    { const char * tb_v3294 = "// (прямоугольник, круг или буква), а видеокарта рисует их все разом — по тем же правилам\n"; *(const char * *)tb_grow(v_lines) = tb_v3294; }
    { const char * tb_v3295 = "// точек, что и процессор (tb_draw_* ниже). Mac — Metal, Linux и Windows — Vulkan.\n"; *(const char * *)tb_grow(v_lines) = tb_v3295; }
    { const char * tb_v3296 = "// Если видеокарты нет (нет драйвера Vulkan, нет экрана) — рисуем как раньше, на процессоре.\n"; *(const char * *)tb_grow(v_lines) = tb_v3296; }
    { const char * tb_v3297 = "//   TB_GPU=0        — всегда на процессоре\n"; *(const char * *)tb_grow(v_lines) = tb_v3297; }
    { const char * tb_v3298 = "//   TB_GPU_CHECK=1  — рисовать и там и там и сверять каждый кадр точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v3298; }
    { const char * tb_v3299 = "//   TB_GPU_INFO=1   — сказать, чем рисуем\n"; *(const char * *)tb_grow(v_lines) = tb_v3299; }
    { const char * tb_v3300 = "typedef struct { int32_t x0, y0, x1, y1, ox, oy; uint32_t c, m; } tb_ginst;   // 32 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v3300; }
    { const char * tb_v3301 = "enum { TB_GI_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v3301; }
    { const char * tb_v3302 = "TB_API int tb_gpu_on = 0, tb_gpu_check = 0, tb_gpu_first = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3302; }
    { const char * tb_v3303 = "TB_API tb_ginst *tb_gi = 0;            // память экземпляров (видна видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v3303; }
    { const char * tb_v3304 = "TB_API int tb_gin = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3304; }
    { const char * tb_v3305 = "TB_API uint32_t *tb_gpu_back = 0;      // TB_GPU_CHECK: кадр, прочитанный обратно с видеокарты\n"; *(const char * *)tb_grow(v_lines) = tb_v3305; }
    { const char * tb_v3306 = "TB_API long long tb_gpu_frames = 0, tb_gpu_bad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3306; }
    { const char * tb_v3307 = "TB_API void tb_gpu_flush(int present);   // своя у каждой системы: Metal или Vulkan\n"; *(const char * *)tb_grow(v_lines) = tb_v3307; }
    { const char * tb_v3308 = "TB_API int tb_gpu_want(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3308; }
    { const char * tb_v3309 = "    const char *e = getenv(\"TB_GPU\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3309; }
    { const char * tb_v3310 = "    tb_gpu_check = getenv(\"TB_GPU_CHECK\") != 0 && getenv(\"TB_GPU_CHECK\")[0] == '1';\n"; *(const char * *)tb_grow(v_lines) = tb_v3310; }
    { const char * tb_v3311 = "    return !(e && e[0] == '0');\n"; *(const char * *)tb_grow(v_lines) = tb_v3311; }
    { const char * tb_v3312 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3312; }
    { const char * tb_v3313 = "TB_API void tb_gpu_say(const char *what) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3313; }
    { const char * tb_v3314 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3314; }
    { const char * tb_v3315 = "    if ((e && e[0] == '1') || tb_gpu_check) fprintf(stderr, \"окно: рисует %s\\n\", what);\n"; *(const char * *)tb_grow(v_lines) = tb_v3315; }
    { const char * tb_v3316 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3316; }
    { const char * tb_v3317 = "TB_API void tb_gpu_report(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3317; }
    { const char * tb_v3318 = "    fprintf(stderr, \"TB_GPU_CHECK: кадров %lld, разошлось %lld\\n\", tb_gpu_frames, tb_gpu_bad);\n"; *(const char * *)tb_grow(v_lines) = tb_v3318; }
    { const char * tb_v3319 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3319; }
    { const char * tb_v3320 = "// сверить кадр видеокарты с кадром процессора (видны только младшие 24 бита цвета)\n"; *(const char * *)tb_grow(v_lines) = tb_v3320; }
    { const char * tb_v3321 = "TB_API void tb_gpu_compare(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3321; }
    { const char * tb_v3322 = "    if (!tb_gpu_back) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3322; }
    { const char * tb_v3323 = "    tb_gpu_frames++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3323; }
    { const char * tb_v3324 = "    long long n = (long long)tb_gw * tb_gh, bad = 0, first = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3324; }
    { const char * tb_v3325 = "    for (long long i = 0; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3325; }
    { const char * tb_v3326 = "        if (((tb_gpu_back[i] ^ tb_px[i]) & 0xFFFFFF) != 0) { if (first < 0) first = i; bad++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3326; }
    { const char * tb_v3327 = "    if (bad) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3327; }
    { const char * tb_v3328 = "        tb_gpu_bad++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3328; }
    { const char * tb_v3329 = "        if (tb_gpu_bad <= 5)\n"; *(const char * *)tb_grow(v_lines) = tb_v3329; }
    { const char * tb_v3330 = "            fprintf(stderr, \"TB_GPU_CHECK: кадр %lld: не совпало точек %lld, первая x=%lld y=%lld: видеокарта %06x, процессор %06x\\n\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3330; }
    { const char * tb_v3331 = "                tb_gpu_frames, bad, first % tb_gw, first / tb_gw, tb_gpu_back[first] & 0xFFFFFF, tb_px[first] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v3331; }
    { const char * tb_v3332 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3332; }
    { const char * tb_v3333 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3333; }
    { const char * tb_v3334 = "TB_INL void tb_gpu_add(long long x0, long long y0, long long x1, long long y1, long long ox, long long oy, uint32_t c, uint32_t m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3334; }
    { const char * tb_v3335 = "    if (tb_gin == TB_GI_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3335; }
    { const char * tb_v3336 = "    tb_ginst *g = &tb_gi[tb_gin++];\n"; *(const char * *)tb_grow(v_lines) = tb_v3336; }
    { const char * tb_v3337 = "    g->x0 = (int32_t)x0; g->y0 = (int32_t)y0; g->x1 = (int32_t)x1; g->y1 = (int32_t)y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3337; }
    { const char * tb_v3338 = "    g->ox = (int32_t)ox; g->oy = (int32_t)oy; g->c = c; g->m = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v3338; }
    { const char * tb_v3339 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3339; }
    { const char * tb_v3340 = "// прямоугольник: обрезан окном; соседние полоски одного цвета склеиваются (линии, точки по одной)\n"; *(const char * *)tb_grow(v_lines) = tb_v3340; }
    { const char * tb_v3341 = "TB_API void tb_gpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3341; }
    { const char * tb_v3342 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v3342; }
    { const char * tb_v3343 = "    if (x0 >= x1 || y0 >= y1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3343; }
    { const char * tb_v3344 = "    uint32_t cc = (uint32_t)c & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v3344; }
    { const char * tb_v3345 = "    if (tb_gin > 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3345; }
    { const char * tb_v3346 = "        tb_ginst *g = &tb_gi[tb_gin - 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v3346; }
    { const char * tb_v3347 = "        if (g->m == 0 && g->c == cc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3347; }
    { const char * tb_v3348 = "            if (g->y0 == y0 && g->y1 == y1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3348; }
    { const char * tb_v3349 = "                if (g->x1 == x0) { g->x1 = (int32_t)x1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3349; }
    { const char * tb_v3350 = "                if (g->x0 == x1) { g->x0 = (int32_t)x0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3350; }
    { const char * tb_v3351 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v3351; }
    { const char * tb_v3352 = "            if (g->x0 == x0 && g->x1 == x1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3352; }
    { const char * tb_v3353 = "                if (g->y1 == y0) { g->y1 = (int32_t)y1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3353; }
    { const char * tb_v3354 = "                if (g->y0 == y1) { g->y0 = (int32_t)y0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3354; }
    { const char * tb_v3355 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v3355; }
    { const char * tb_v3356 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3356; }
    { const char * tb_v3357 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3357; }
    { const char * tb_v3358 = "    tb_gpu_add(x0, y0, x1, y1, 0, 0, cc, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3358; }
    { const char * tb_v3359 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3359; }
    { const char * tb_v3360 = "TB_API void tb_gpu_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3360; }
    { const char * tb_v3361 = "    if (r < 0 || cx + r < 0 || cy + r < 0 || cx - r >= tb_gw || cy - r >= tb_gh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3361; }
    { const char * tb_v3362 = "    if (r <= 16384) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3362; }
    { const char * tb_v3363 = "        long long x0 = cx - r < 0 ? 0 : cx - r, y0 = cy - r < 0 ? 0 : cy - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v3363; }
    { const char * tb_v3364 = "        long long x1 = cx + r + 1 > tb_gw ? tb_gw : cx + r + 1, y1 = cy + r + 1 > tb_gh ? tb_gh : cy + r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3364; }
    { const char * tb_v3365 = "        tb_gpu_add(x0, y0, x1, y1, cx, cy, (uint32_t)c & 0xFFFFFF, (1u << 30) | (uint32_t)r);\n"; *(const char * *)tb_grow(v_lines) = tb_v3365; }
    { const char * tb_v3366 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3366; }
    { const char * tb_v3367 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3367; }
    { const char * tb_v3368 = "    // огромный круг: по строкам, полосками (то же правило i*i + j*j <= r*r + r)\n"; *(const char * *)tb_grow(v_lines) = tb_v3368; }
    { const char * tb_v3369 = "    long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v3369; }
